import java.lang.annotation.*;
public class A1 {
    @Retention(RetentionPolicy.RUNTIME)
    @interface Level { int value() default 3; }
    @Level(5) static class High { }
    @Level static class Default { }
    static class None { }
    public static void main(String[] args) {
        System.out.println(High.class.getAnnotation(Level.class).value() + " "
                + Default.class.getAnnotation(Level.class).value() + " "
                + None.class.getAnnotation(Level.class));
    }
}

